import java.util.Stack;

public class Solution {
    public static boolean isValid(String s) {
        Stack<Character> stack = new Stack<>();

        for (char c : s.toCharArray()) {
            if (c == '(' || c == '{' || c == '[') {
                stack.push(c);
            } else {
                if (stack.empty()) return false;
                if (c == ')' && stack.peek() != '(') return false;
                if (c == '}' && stack.peek() != '{') return false;
                if (c == ']' && stack.peek() != '[') return false;
                stack.pop();
            }
        }

        return stack.empty();
    }

    public static String[] generateParenthesis(int n) {
        Stack<String> stack = new Stack<>();
        String[] result = new String[n * 2];
        int index = 0;

        generateParenthesisHelper(stack, result, index, n);

        return result;
    }

    private static void generateParenthesisHelper(Stack<String> stack, String[] result, int index, int n) {
        if (stack.size() == n * 2) {
            result[index] = stack.toString();
            return;
        }

        stack.push("(");
        generateParenthesisHelper(stack, result, index, n);
        stack.pop();

        stack.push(")");
        generateParenthesisHelper(stack, result, index, n);
        stack.pop();
    }
}

