    public List<Integer> nextPermutation(int[] nums) {
        int i = nums.length - 1;
        while (i > 0 && nums[i - 1] >= nums[i]) {
            i--;
        }
        if (i <= 0) {
            return Arrays.asList(nums);
        }
        int j = nums.length - 1;
        while (nums[j] <= nums[i - 1]) {
