    stack = []
    count = 0

    for c in s:
        if c in '([{':
            stack.append(c)
        else:
            if not stack:
                return count
            if c == ')' and stack[-1] == '(':
                stack.pop()
                count += 1
            if c == '}' and stack[-1] == '{':
                stack.pop()
                count += 1
            if c == ']' and stack[-1] == '[':
