    if (x == target) return 0;
    if (target == 1) return 1;
    if (x > target) return Math.min(2 * target - 1, 2 * (x - target));

    int k = 0;
    long p = x;
    while (p < target) {
        k++;
        p *= x;
    }

    int ans = Integer.MAX_VALUE;
    long d = 1;

    for (int i = k - 1; i >= 0; i--) {
        while (p >= target + d * (1 - x)) {
            p -= d;
            ans = Math.min(ans, i + (int) (Math.log(target / d) / Math.log(2) + 1) + (int) (d == 1 ? -1 : 0));
        }
        d = d * x + 1;
    }

    return ans;
}
