public String removeKdigits(String num, int k) {
    int n = num.length();
    if (k >= n) return "0";
    int[] stack = new int[n];
    int top = 0;
    for (int i = 0; i < n; i++) {
        while (top > 0 && stack[top - 1] > num.charAt(i) - '0' && k > 0) {
            top--;
            k--;
        }
        stack[top++] = num.charAt(i) - '0';
    }
    while (k > 0) {
        top--;
        k--;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < top; i++) {
        sb.append(stack[i]);
    }
